"""navera_lite/night.py — night vision without the learning: normalised cross-correlation (NCC), the ground footprint
of a camera, how much of the reference square a turned footprint covers, preparing a night frame (north-up, map
scale), locating it by template matching, and the motion gate that checks every fix. Part of NAVERA Lite, the
course's teaching stack (mission 25). Written for the course; it is not NAVERA code.

Conventions: an image is a numpy array img[row, column] = img[y, x], (0, 0) at the TOP-LEFT, y grows DOWNWARDS
(mission 08). A point is (x, y) = (column, row); a pixel's coordinates are those of its CENTRE, so the centre point
of a w × h picture is ((w − 1)/2, (h − 1)/2). Headings are clockwise from north, in degrees: heading_deg is where
the TOP of the camera picture points. North-up pictures have north at the top and east on the right.
The reference square is the piece of map a night matcher compares the frame with (NAVERA: 512 map pixels at
zoom 17, about 496 m at Sousse).
"""
import math

import cv2
import numpy as np

from navera_lite.geo import haversine_m

MIN_COVERAGE = 0.85        # a prepared frame must cover at least 85 % of the reference square (NAVERA's rule)
V_MAX_MPS = 30.0           # the motion gate's speed limit, m/s (NAVERA's default for a drone)
GATE_MARGIN_M = 30.0       # the motion gate's margin, metres (NAVERA's default)


# ====================================================================== comparing two pictures (session 1)

# from mission 25 — finished: read it, use it, do not change it
def ncc(a, b):
    """The normalised cross-correlation of two pictures of the same shape: subtract each picture's mean, then
    the sum of the products divided by the square root of (sum of squares of a) × (sum of squares of b).
    +1: the same picture up to brightness and contrast (b = gain·a + offset, gain > 0); −1: the negative;
    about 0: unrelated. If one picture is uniform (nothing to compare), return 0.0.

    Inputs: two arrays of the same shape (uint8 or float; work in float64). Returns a Python float in [−1, 1].
    Example: ncc(np.array([[10, 20], [30, 40]]), np.array([[100, 120], [140, 160]])) → 1.0
             ncc(np.array([[10, 20], [30, 40]]), np.array([[9, 7], [5, 3]]))         → -1.0
    """
    a = np.asarray(a, dtype=np.float64)
    b = np.asarray(b, dtype=np.float64)
    if a.shape != b.shape:
        raise ValueError(f"ncc needs two pictures of the same shape, got {a.shape} and {b.shape}")
    a = a - a.mean()
    b = b - b.mean()
    den = math.sqrt(float((a * a).sum()) * float((b * b).sum()))
    if den < 1e-12:
        return 0.0
    return float((a * b).sum() / den)


# ====================================================================== the camera's footprint and coverage

# from mission 25 — finished: read it, use it, do not change it
def footprint_m(alt_m, hfov_deg, vfov_deg):
    """The ground rectangle seen by a downward (nadir) camera over flat ground: its width (along the picture's
    x axis) and its height (along the picture's y axis), in metres, from the height above ground and the
    horizontal and vertical fields of view (lesson §3, mission 18).

    Inputs: alt_m > 0; 0 < hfov_deg, vfov_deg < 180. Returns (width_m, height_m), two floats.
    Example: footprint_m(100.0, 90.0, 60.0) → (200.0, 115.47…)
    """
    if alt_m <= 0 or not (0 < hfov_deg < 180) or not (0 < vfov_deg < 180):
        raise ValueError(f"need alt_m > 0 and fields of view in (0, 180), got {alt_m}, {hfov_deg}, {vfov_deg}")
    w = 2.0 * alt_m * math.tan(math.radians(hfov_deg) / 2.0)
    h = 2.0 * alt_m * math.tan(math.radians(vfov_deg) / 2.0)
    return float(w), float(h)


# from mission 25 — finished: read it, use it, do not change it
def coverage(width_m, height_m, heading_deg, ref_m):
    """The share (0 to 1) of a north-up reference square of side ref_m that a camera footprint covers, when
    both have the same centre and the footprint (width_m × height_m) is turned by heading_deg (lesson §3).
    Exact geometry or a fine grid of sample points (≥ 200 × 200) are both fine: the answer must be right to
    ±0.005.

    Inputs: metres > 0, degrees. Returns a float in [0, 1].
    Example: coverage(600.0, 300.0, 0.0, 400.0) → 0.75        (the full width, 300 of the 400 m of height)
             coverage(600.0, 300.0, 90.0, 400.0) → 0.75       (turned a quarter: now the full height)
    """
    if width_m <= 0 or height_m <= 0 or ref_m <= 0:
        raise ValueError(f"sizes must be > 0, got {width_m}, {height_m}, {ref_m}")
    a = math.radians(heading_deg)
    c, s = math.cos(a), math.sin(a)
    hw, hh = width_m / 2.0, height_m / 2.0
    rect = np.array([[c * x - s * y, s * x + c * y] for x, y in ((-hw, -hh), (hw, -hh), (hw, hh), (-hw, hh))],
                    np.float32)
    r = ref_m / 2.0
    square = np.array([[-r, -r], [r, -r], [r, r], [-r, r]], np.float32)
    area, _ = cv2.intersectConvexConvex(rect, square)
    return float(min(1.0, max(0.0, area / (ref_m * ref_m))))


# from mission 25 — finished: read it, use it, do not change it
def min_altitude(hfov_deg, vfov_deg, heading_deg, ref_m, need=MIN_COVERAGE, lo_m=10.0, hi_m=5000.0, tol_m=0.5):
    """The lowest height above ground at which the footprint covers at least `need` of the reference square, for
    this camera and heading — found by bisection with YOUR footprint_m and coverage (coverage grows with height).
    Returns metres (float), or None if even hi_m is not enough.
    Example: min_altitude(84.0, 68.0, 0.0, 495.8) → about 311 m
    """
    # from mission 25 — finished: read it, use it, do not change it
    def ok(alt):
        w, h = footprint_m(alt, hfov_deg, vfov_deg)
        return coverage(w, h, heading_deg, ref_m) >= need
    if not ok(hi_m):
        return None
    lo, hi = lo_m, hi_m
    while hi - lo > tol_m:
        mid = (lo + hi) / 2.0
        if ok(mid):
            hi = mid
        else:
            lo = mid
    return float(hi)


# ====================================================================== preparing a night frame

# from mission 25 — finished: read it, use it, do not change it
def prepare(frame, alt_m, hfov_deg, vfov_deg, heading_deg, map_m_per_px, out_px, need=MIN_COVERAGE):
    """Make a downward night frame comparable with a north-up map patch of out_px × out_px pixels at
    map_m_per_px metres per pixel: ONE warp that scales the frame to the map's metres per pixel, turns it
    north-up, and puts the frame's centre point on the patch's centre point ((out_px − 1)/2, (out_px − 1)/2).
    Pixels the frame does not cover are 0. Then the coverage of the reference square (side out_px ·
    map_m_per_px), with your footprint_m and coverage: below `need`, the frame is refused (lesson §4).

    Inputs: frame (h, w) uint8 grey; heights in metres; angles in degrees (heading = where the frame's TOP points,
    clockwise from north). Returns (patch, cov, reason): patch (out_px, out_px) uint8, or None when refused;
    cov the coverage (float); reason "ok" or a sentence that contains "fly higher".
    Example: prepare(np.full((512, 640), 200, np.uint8), 400.0, 75.0, 63.0, 0.0, 7.75, 64)
             → (a 64 × 64 patch of 200s (the footprint covers it all but a sliver), 0.988…, "ok")
    """
    frame = np.asarray(frame)
    h, w = frame.shape[:2]
    fw, fh = footprint_m(alt_m, hfov_deg, vfov_deg)
    ref_m = out_px * map_m_per_px
    cov = coverage(fw, fh, heading_deg, ref_m)
    if cov < need:
        return None, cov, (f"the frame covers {cov:.0%} of the {ref_m:.0f} m reference square, "
                           f"less than {need:.0%}: fly higher")
    sx = (fw / w) / map_m_per_px            # output pixels per frame pixel, along x and along y
    sy = (fh / h) / map_m_per_px
    a = math.radians(heading_deg)
    c, s = math.cos(a), math.sin(a)
    # frame (x right, y down) → north-up patch: scale, then turn clockwise by the heading
    A = np.array([[c * sx, -s * sy], [s * sx, c * sy]])
    cin = np.array([(w - 1) / 2.0, (h - 1) / 2.0])
    cout = np.array([(out_px - 1) / 2.0, (out_px - 1) / 2.0])
    M = np.hstack([A, (cout - A @ cin)[:, None]])
    patch = cv2.warpAffine(frame, M, (out_px, out_px), flags=cv2.INTER_AREA, borderMode=cv2.BORDER_CONSTANT,
                           borderValue=0)
    return patch, cov, "ok"


# from mission 25 — finished: read it, use it, do not change it
def ncc_locate(template, search):
    """Find a small picture (the template) inside a larger one (the search area) by NCC at every position, with
    OpenCV's matchTemplate in its normalised mode (cv2.TM_CCOEFF_NORMED). Returns where the template's CENTRE
    point lies relative to the search area's CENTRE point, in pixels (dx > 0: to the right, dy > 0: down), and the
    best NCC score.

    Inputs: template (th, tw) and search (sh, sw) uint8 grey, sh ≥ th and sw ≥ tw.
    Returns (dx, dy, score): floats.
    Example: a 9 × 9 search area, and the template = its 5 × 5 block with top-left corner at (x=3, y=1)
             → (1.0, -1.0, 1.0)     (the block's centre (5, 3) is 1 px right of and 1 px above the centre (4, 4))
    """
    t = np.asarray(template, np.uint8)
    s = np.asarray(search, np.uint8)
    r = cv2.matchTemplate(s, t, cv2.TM_CCOEFF_NORMED)
    _, best, _, (mx, my) = cv2.minMaxLoc(r)
    dx = mx + (t.shape[1] - 1) / 2.0 - (s.shape[1] - 1) / 2.0
    dy = my + (t.shape[0] - 1) / 2.0 - (s.shape[0] - 1) / 2.0
    return float(dx), float(dy), float(best)


# ====================================================================== checking a fix with physics

# from mission 25 — finished: read it, use it, do not change it
def motion_gate(anchor, t_anchor_s, fix, t_s, v_max_mps=V_MAX_MPS, margin_m=GATE_MARGIN_M):
    """Accept a new night fix only if the vehicle could have got there: the distance from the anchor (the last
    ACCEPTED fix) must not exceed v_max_mps × (t_s − t_anchor_s) + margin_m (lesson §5). A negative elapsed time
    counts as 0. Without an anchor (None), the first fix is accepted.

    Inputs: anchor None or (lat, lon), fix (lat, lon) in degrees; times in seconds.
    Returns (ok, reason): ok a bool; reason "ok", "first fix", or a sentence that contains the word "jump", the
    distance and the limit in whole metres, e.g. "implausible jump 238 m in 2.0 s (max 90 m)".
    Example: motion_gate((35.8, 10.6), 0.0, (35.8, 10.601), 1.0) → (False, 'implausible jump 90 m in 1.0 s (max 60 m)')
             motion_gate((35.8, 10.6), 0.0, (35.8, 10.601), 3.0) → (True, 'ok')        (the limit is now 120 m)
    """
    if anchor is None:
        return True, "first fix"
    jump = float(haversine_m(anchor[0], anchor[1], fix[0], fix[1]))
    dt = max(0.0, t_s - t_anchor_s)
    reach = v_max_mps * dt + margin_m
    if jump > reach:
        return False, f"implausible jump {jump:.0f} m in {dt:.1f} s (max {reach:.0f} m)"
    return True, "ok"
